// XMind ships two tabs of 配色方案.  Every group is six colours with fixed
// roles: 0 = canvas/backdrop, 1 = secondary surface, 2..5 = branch colours,
// the last one doubles as the central-topic fill.  `strips` is the special
// three-stop artwork XMind draws for 彩虹 (one gradient per branch row).
// `variants` are the six single-accent quick themes shown *below* the
// drop-down for that scheme (FINDINGS §39); each accent is one swatch.

export interface PaletteVariant {
  /** One of the scheme's six swatches; also the central-topic fill. */
  accent: string;
  /** Pale map backdrop measured from the shipped colour themes. */
  bg: string;
  ink: string;
  center: string;
  /** Six same-hue tones so a saved colour list keeps its length. */
  branches: string[];
}

export interface PaletteDef {
  id: string;
  name: string;
  /** Six hexes, roles as described above. */
  colors: string[];
  /** The six quick themes for this scheme, swatch order. */
  variants: PaletteVariant[];
  /** Optional 6×3 gradient stops for the 彩虹 card. */
  strips?: string[][];
  /** 彩虹 only: the 12-hue branch cycle it actually paints with. */
  cycle?: string[];
}

